INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$a3e87535$SATQ$, $SATQ$2ce12901-ba63-4561-9077-97d4b4b4fc47$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Julia Alvarez&rsquo;s 1994 novel <em>In the Time of the Butterflies, </em>a fictionalized account of the lives of the Mirabal <span aria-hidden="true">______</span><span class="sr-only">blank</span> can serve as a starting point for those wanting to explore how the rule of dictator Rafael Trujillo<em>&nbsp;</em>has been represented in Dominican American literature.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"040965c9-86c6-4013-9cda-17b54a9505c8","content":"<p>sisters, and</p>"},{"id":"9bcec556-4110-43e6-8ea1-027be840f3f2","content":"<p>sisters and</p>"},{"id":"05d06d46-67a3-4490-8f80-8cd99fb9bb8d","content":"<p>sisters,</p>"},{"id":"5459ed33-c2b9-4ddc-b949-60e3c7131373","content":"<p>sisters</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["05d06d46-67a3-4490-8f80-8cd99fb9bb8d"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the punctuation of a supplementary element within a sentence. The comma after "sisters" pairs with the comma after "<em>Butterflies</em>" to separate the supplementary element "a fictionalized account of the lives of the Mirabal sisters" from the rest of the sentence. This supplementary element functions to describe the novel <em>In the Time of the Butterflies</em>, and the pair of commas indicates that this element could be removed without affecting the grammatical coherence of the sentence.</p><p>Choice A is incorrect because a comma and conjunction can&rsquo;t be used in this way to separate the supplementary element from the rest of the sentence. Choice B is incorrect because it fails to use appropriate punctuation to separate the supplementary element from the rest of the sentence. Choice D is incorrect because it fails to use appropriate punctuation to separate the supplementary element from the rest of the sentence.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a3e87535","external_id":"2ce12901-ba63-4561-9077-97d4b4b4fc47","vaultid":null,"uId":"3d6cf5db-2bd3-47ce-90ea-ad9d40f9a24c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Julia Alvarez&rsquo;s 1994 novel <em>In the Time of the Butterflies, </em>a fictionalized account of the lives of the Mirabal <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> can serve as a starting point for those wanting to explore how the rule of dictator Rafael Trujillo<em>&nbsp;</em>has been represented in Dominican American literature.&nbsp;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"040965c9-86c6-4013-9cda-17b54a9505c8","content":"<p>sisters, and</p>"},{"id":"9bcec556-4110-43e6-8ea1-027be840f3f2","content":"<p>sisters and</p>"},{"id":"05d06d46-67a3-4490-8f80-8cd99fb9bb8d","content":"<p>sisters,</p>"},{"id":"5459ed33-c2b9-4ddc-b949-60e3c7131373","content":"<p>sisters</p>"}],"keys":["05d06d46-67a3-4490-8f80-8cd99fb9bb8d"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the punctuation of a supplementary element within a sentence. The comma after \"sisters\" pairs with the comma after \"<em>Butterflies</em>\" to separate the supplementary element \"a fictionalized account of the lives of the Mirabal sisters\" from the rest of the sentence. This supplementary element functions to describe the novel <em>In the Time of the Butterflies</em>, and the pair of commas indicates that this element could be removed without affecting the grammatical coherence of the sentence.</p><p>Choice A is incorrect because a comma and conjunction can&rsquo;t be used in this way to separate the supplementary element from the rest of the sentence. Choice B is incorrect because it fails to use appropriate punctuation to separate the supplementary element from the rest of the sentence. Choice D is incorrect because it fails to use appropriate punctuation to separate the supplementary element from the rest of the sentence.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323048,"updateDate":1730147323048}$SATQ$::jsonb, 1730147323048, 1730147323048),
    ($SATQ$a427a52c$SATQ$, $SATQ$4b0deb5a-da7b-494d-a3f2-347dc606dfed$SATQ$::uuid, $SATQ$bd5feb20-74b0-43e9-8b72-ce74e714f9ba$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>The Lion Light system, developed by Kenyan inventor Richard Turere, consists of LED lights installed around the perimeter of livestock pastures. Powered with <span aria-hidden="true">______</span><span class="sr-only">blank</span> the blinking LEDs keep lions away at night, thus protecting the livestock without risking harm to the endangered lions.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"f5e03880-f1a7-48e8-84e9-86703e6a53be","content":"<p>energy collected, by solar panels, during the day</p>"},{"id":"2b80d36b-56b0-40fb-8128-ae9efa741996","content":"<p>energy collected by solar panels during the day</p>"},{"id":"1fb415d9-fbaa-4c52-8b38-af5211d237f8","content":"<p>energy collected by solar panels during the day,</p>"},{"id":"81eac3c6-2b93-4579-993a-12f9fd08aaea","content":"<p>energy, collected by solar panels during the day,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["1fb415d9-fbaa-4c52-8b38-af5211d237f8"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is punctuation between a supplementary phrase and a main clause. This choice correctly uses a comma to mark the boundary between the supplementary phrase (&ldquo;powered&hellip;day&rdquo;), which describes how the LEDs are powered, and the main clause (&ldquo;the blinking&hellip;night&rdquo;). </p><p>Choice A is incorrect because it fails to mark the boundary between the supplementary phrase and the main clause with appropriate punctuation. Furthermore, placing commas around the phrase &ldquo;by solar panels&rdquo; suggests that it could be removed without affecting the coherence of the sentence, which isn&rsquo;t the case. Choice B is incorrect because it fails to mark the boundary between the supplementary phrase and the main clause with appropriate punctuation. Choice D is incorrect. Placing commas around the phrase &ldquo;collected by solar panels during the day&Prime; suggests that it could be removed without affecting the coherence of the sentence, which isn&rsquo;t the case. </p>$SATQ$, false, 0, $SATQ$OSP-697-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$d34876bc-a832-4a25-abb8-3f4c0d25056c$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"a427a52c","external_id":"4b0deb5a-da7b-494d-a3f2-347dc606dfed","vaultid":"bd5feb20-74b0-43e9-8b72-ce74e714f9ba","uId":"e475f0a6-aa02-4df4-922b-7907b124f21f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>The Lion Light system, developed by Kenyan inventor Richard Turere, consists of LED lights installed around the perimeter of livestock pastures. Powered with <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the blinking LEDs keep lions away at night, thus protecting the livestock without risking harm to the endangered lions.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"f5e03880-f1a7-48e8-84e9-86703e6a53be","content":"<p>energy collected, by solar panels, during the day</p>"},{"id":"2b80d36b-56b0-40fb-8128-ae9efa741996","content":"<p>energy collected by solar panels during the day</p>"},{"id":"1fb415d9-fbaa-4c52-8b38-af5211d237f8","content":"<p>energy collected by solar panels during the day,</p>"},{"id":"81eac3c6-2b93-4579-993a-12f9fd08aaea","content":"<p>energy, collected by solar panels during the day,</p>"}],"keys":["1fb415d9-fbaa-4c52-8b38-af5211d237f8"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is punctuation between a supplementary phrase and a main clause. This choice correctly uses a comma to mark the boundary between the supplementary phrase (&ldquo;powered&hellip;day&rdquo;), which describes how the LEDs are powered, and the main clause (&ldquo;the blinking&hellip;night&rdquo;). </p><p>Choice A is incorrect because it fails to mark the boundary between the supplementary phrase and the main clause with appropriate punctuation. Furthermore, placing commas around the phrase &ldquo;by solar panels&rdquo; suggests that it could be removed without affecting the coherence of the sentence, which isn&rsquo;t the case. Choice B is incorrect because it fails to mark the boundary between the supplementary phrase and the main clause with appropriate punctuation. Choice D is incorrect. Placing commas around the phrase &ldquo;collected by solar panels during the day&Prime; suggests that it could be removed without affecting the coherence of the sentence, which isn&rsquo;t the case. </p>","parenttemplatename":"OSP-697-SEC","parenttemplateid":"","templateclusterid":"d34876bc-a832-4a25-abb8-3f4c0d25056c","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959347,"updateDate":1691007959347}$SATQ$::jsonb, 1691007959347, 1691007959347),
    ($SATQ$a466679a$SATQ$, $SATQ$2e13e59a-2ea7-4c98-b37e-06a129472be2$SATQ$::uuid, $SATQ$9d970279-71cc-4670-bbdb-2dea618082df$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>In 1976, the Inuit rock group Sikumiut recorded the album <em>People of the Ice</em>. Though only their first record, it shows a band already skilled at the difficult task of making music that sounds easy and fun. On songs like &ldquo;Utirumavunga,&rdquo; Lucassie Koperqualuk&rsquo;s guitar riffs effortlessly <span aria-hidden="true">______</span><span class="sr-only">blank</span> Charlie Adams&rsquo;s delightfully catchy vocal melodies.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"d7d178d5-5f50-45e4-9c6e-e44deb7fcf87","content":"<p>blend, with</p>"},{"id":"c8f2118a-179c-44c5-9c4f-7f822f15360a","content":"<p>blend. With</p>"},{"id":"2ca46a2e-f682-41a0-b5d3-968d1176cbb6","content":"<p>blend; with</p>"},{"id":"6f490a9e-3124-4a1c-ab33-6afc65a7e248","content":"<p>blend with</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["6f490a9e-3124-4a1c-ab33-6afc65a7e248"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is punctuation between a verb and a prepositional phrase. No punctuation is needed between the verb &ldquo;blend&rdquo; and the prepositional phrase &ldquo;with Charlie Adams&rsquo;s delightfully catchy vocal melodies.&rdquo; The prepositional phrase completes the idea of the sentence, explaining with what Koperqualuk&rsquo;s guitar riffs blend. </p><p>Choice A is incorrect because no punctuation is needed between the verb and the prepositional phrase. &nbsp;Choice B is incorrect because no punctuation is needed between the verb and the prepositional phrase.&nbsp;&nbsp;Choice C is incorrect because no punctuation is needed between the verb and the prepositional phrase. &nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-739-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$a8d2d266-434c-417d-8cba-95d23cea9378$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"a466679a","external_id":"2e13e59a-2ea7-4c98-b37e-06a129472be2","vaultid":"9d970279-71cc-4670-bbdb-2dea618082df","uId":"8e7f2a7a-5784-4757-bf0c-248c2f6b7667","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>In 1976, the Inuit rock group Sikumiut recorded the album <em>People of the Ice</em>. Though only their first record, it shows a band already skilled at the difficult task of making music that sounds easy and fun. On songs like &ldquo;Utirumavunga,&rdquo; Lucassie Koperqualuk&rsquo;s guitar riffs effortlessly <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> Charlie Adams&rsquo;s delightfully catchy vocal melodies.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"d7d178d5-5f50-45e4-9c6e-e44deb7fcf87","content":"<p>blend, with</p>"},{"id":"c8f2118a-179c-44c5-9c4f-7f822f15360a","content":"<p>blend. With</p>"},{"id":"2ca46a2e-f682-41a0-b5d3-968d1176cbb6","content":"<p>blend; with</p>"},{"id":"6f490a9e-3124-4a1c-ab33-6afc65a7e248","content":"<p>blend with</p>"}],"keys":["6f490a9e-3124-4a1c-ab33-6afc65a7e248"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is punctuation between a verb and a prepositional phrase. No punctuation is needed between the verb &ldquo;blend&rdquo; and the prepositional phrase &ldquo;with Charlie Adams&rsquo;s delightfully catchy vocal melodies.&rdquo; The prepositional phrase completes the idea of the sentence, explaining with what Koperqualuk&rsquo;s guitar riffs blend. </p><p>Choice A is incorrect because no punctuation is needed between the verb and the prepositional phrase. &nbsp;Choice B is incorrect because no punctuation is needed between the verb and the prepositional phrase.&nbsp;&nbsp;Choice C is incorrect because no punctuation is needed between the verb and the prepositional phrase. &nbsp;</p>","parenttemplatename":"OSP-739-SEC","parenttemplateid":"","templateclusterid":"a8d2d266-434c-417d-8cba-95d23cea9378","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959349,"updateDate":1691007959349}$SATQ$::jsonb, 1691007959349, 1691007959349),
    ($SATQ$a5079e0d$SATQ$, $SATQ$25a17e6b-87b8-4a28-bc40-b8d65e369837$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Horsepower is a unit of measurement used to determine how much power a vehicle produces. The measurement is based on how much and how quickly weight can be <span aria-hidden="true">______</span><span class="sr-only">blank</span> one unit of mechanical horsepower is equivalent to the amount of power it takes to lift 550 pounds one foot off the ground in one second.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"dfd8d5ef-48e6-4673-a6ae-063ca709c566","content":"<p>moved, for example,</p>"},{"id":"ec63a4a0-d9fa-44c1-85a7-5fe38795ff2d","content":"<p>moved,</p>"},{"id":"ccd5e490-94d7-4926-91a4-24390e2898a3","content":"<p>moved; for example,</p>"},{"id":"c0650b9c-3f5e-47dd-868a-2f87b3b6fd98","content":"<p>moved</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["ccd5e490-94d7-4926-91a4-24390e2898a3"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the use of punctuation within a sentence. This choice uses a semicolon in a conventional way to join the first main clause ("The measurement...moved") and the second main clause ("for example...second").</p><p>Choice A is incorrect because it results in a comma splice. Without a coordinating conjunction, a comma can&rsquo;t be used in this way to join the two main clauses ("The measurement&hellip;moved" and "for example&hellip;second"). Choice B is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join the two main clauses ("The measurement&hellip;moved" and "one unit&hellip;second"). Choice D is incorrect because it results in a run-on sentence. The two main clauses ("The measurement&hellip;moved" and "one unit&hellip;second") are fused without punctuation and/or a conjunction.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a5079e0d","external_id":"25a17e6b-87b8-4a28-bc40-b8d65e369837","vaultid":null,"uId":"cba3a76f-fba9-4df3-a488-85ad301155c8","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Horsepower is a unit of measurement used to determine how much power a vehicle produces. The measurement is based on how much and how quickly weight can be <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> one unit of mechanical horsepower is equivalent to the amount of power it takes to lift 550 pounds one foot off the ground in one second.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"dfd8d5ef-48e6-4673-a6ae-063ca709c566","content":"<p>moved, for example,</p>"},{"id":"ec63a4a0-d9fa-44c1-85a7-5fe38795ff2d","content":"<p>moved,</p>"},{"id":"ccd5e490-94d7-4926-91a4-24390e2898a3","content":"<p>moved; for example,</p>"},{"id":"c0650b9c-3f5e-47dd-868a-2f87b3b6fd98","content":"<p>moved</p>"}],"keys":["ccd5e490-94d7-4926-91a4-24390e2898a3"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the use of punctuation within a sentence. This choice uses a semicolon in a conventional way to join the first main clause (\"The measurement...moved\") and the second main clause (\"for example...second\").</p><p>Choice A is incorrect because it results in a comma splice. Without a coordinating conjunction, a comma can&rsquo;t be used in this way to join the two main clauses (\"The measurement&hellip;moved\" and \"for example&hellip;second\"). Choice B is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join the two main clauses (\"The measurement&hellip;moved\" and \"one unit&hellip;second\"). Choice D is incorrect because it results in a run-on sentence. The two main clauses (\"The measurement&hellip;moved\" and \"one unit&hellip;second\") are fused without punctuation and/or a conjunction.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323047,"updateDate":1730147323047}$SATQ$::jsonb, 1730147323047, 1730147323047),
    ($SATQ$a75d5984$SATQ$, $SATQ$328ab8a3-7315-4722-b40d-a7d0944ccde3$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Several advantages&mdash;the ability to react strongly with chip components, to avoid interference from other waves, and to be confined within tiny circuits&mdash;<span aria-hidden="true">______</span><span class="sr-only">blank</span> acoustic waves as a promising alternative to electrical waves for transmitting data on computer chips; as a result, researchers are invested in developing more acoustic wave&ndash;based chips.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"5d4d4044-0eda-4618-bd24-7bbc4792a1cb","content":"<p>have positioned</p>"},{"id":"d5b7861f-ba59-4d85-b374-349b226cd5d5","content":"<p>positioning</p>"},{"id":"fba5f788-d6ff-4472-8f45-a22f94ea5d6d","content":"<p>by positioning</p>"},{"id":"8371232d-31b7-4fdc-95b1-174192c39218","content":"<p>having positioned</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["5d4d4044-0eda-4618-bd24-7bbc4792a1cb"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. A main clause requires a finite (tensed) verb to perform the action of the subject. In this case, the subject is "several advantages," and the present perfect tense verb "have positioned" supplies the finite verb to indicate what has made acoustic waves a promising alternative to electrical waves.</p><p>Choice B is incorrect because it results in an ungrammatical sentence. The nonfinite participle "positioning" doesn&rsquo;t supply the main clause with a finite verb. Choice C is incorrect because it results in an ungrammatical sentence. The prepositional phrase "by positioning" doesn&rsquo;t supply the main clause with a finite verb. Choice D is incorrect because it results in an ungrammatical sentence. The nonfinite participle "having positioned" doesn&rsquo;t supply the main clause with a finite verb.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a75d5984","external_id":"328ab8a3-7315-4722-b40d-a7d0944ccde3","vaultid":null,"uId":"5bc42d08-43ae-4643-9cc0-e2840ce0cc96","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Several advantages&mdash;the ability to react strongly with chip components, to avoid interference from other waves, and to be confined within tiny circuits&mdash;<span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> acoustic waves as a promising alternative to electrical waves for transmitting data on computer chips; as a result, researchers are invested in developing more acoustic wave&ndash;based chips.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"5d4d4044-0eda-4618-bd24-7bbc4792a1cb","content":"<p>have positioned</p>"},{"id":"d5b7861f-ba59-4d85-b374-349b226cd5d5","content":"<p>positioning</p>"},{"id":"fba5f788-d6ff-4472-8f45-a22f94ea5d6d","content":"<p>by positioning</p>"},{"id":"8371232d-31b7-4fdc-95b1-174192c39218","content":"<p>having positioned</p>"}],"keys":["5d4d4044-0eda-4618-bd24-7bbc4792a1cb"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. A main clause requires a finite (tensed) verb to perform the action of the subject. In this case, the subject is \"several advantages,\" and the present perfect tense verb \"have positioned\" supplies the finite verb to indicate what has made acoustic waves a promising alternative to electrical waves.</p><p>Choice B is incorrect because it results in an ungrammatical sentence. The nonfinite participle \"positioning\" doesn&rsquo;t supply the main clause with a finite verb. Choice C is incorrect because it results in an ungrammatical sentence. The prepositional phrase \"by positioning\" doesn&rsquo;t supply the main clause with a finite verb. Choice D is incorrect because it results in an ungrammatical sentence. The nonfinite participle \"having positioned\" doesn&rsquo;t supply the main clause with a finite verb.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323051,"updateDate":1730147323051}$SATQ$::jsonb, 1730147323051, 1730147323051),
    ($SATQ$a7c85001$SATQ$, $SATQ$e845817f-2b9b-478e-b657-e6f8392b425b$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Researchers Amit Kumar and Nicholas Epley investigated how <span aria-hidden="true">______</span><span class="sr-only">blank</span> In a series of experiments conducted in <span data-ssml-say-as="date">2022</span>, they found that people performing small acts of kindness underestimated the positive effect their actions had on others. &nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"92e6f5a5-e3f5-49ae-9a99-75550291de42","content":"<p>do people perceive acts of kindness<span data-ssml-say-as=\"characters\">.</span></p>"},{"id":"ac929aa5-07bc-477c-bd1d-971169f489ac","content":"<p>do people perceive acts of kindness<span data-ssml-say-as=\"characters\">?</span> &nbsp;</p>"},{"id":"3784d777-0839-43a3-9046-ac9b6c283787","content":"<p>people perceive acts of kindness<span data-ssml-say-as=\"characters\">?</span></p>"},{"id":"5841eec4-39b4-4f8e-8302-5776daa42ccd","content":"<p>people perceive acts of kindness<span data-ssml-say-as=\"characters\">.</span></p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["5841eec4-39b4-4f8e-8302-5776daa42ccd"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is end-of-sentence punctuation. This choice correctly uses a period to punctuate a declarative sentence that asks an indirect question ("Researchers Amit Kumar and Nicholas Epley investigated how people perceive acts of kindness").</p><p>Choice A is incorrect. The structure of the sentence requires a declarative clause at the end of the sentence that states what Kumar and Epley did, not an interrogative clause that asks a direct question, such as "how do people perceive acts of kindness." Choice B is incorrect. The structure of the sentence requires a declarative clause at the end of the sentence that states what Kumar and Epley did, not an interrogative clause that asks a direct question, such as "how do people perceive acts of kindness?" Choice C is incorrect. It&rsquo;s unconventional to use a question mark in this way to punctuate a declarative sentence that asks an indirect question, such as "Researchers&hellip;kindness."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a7c85001","external_id":"e845817f-2b9b-478e-b657-e6f8392b425b","vaultid":null,"uId":"06e8af75-cf37-43e7-b9e1-9221407e18ca","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Researchers Amit Kumar and Nicholas Epley investigated how <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> In a series of experiments conducted in <span data-ssml-say-as=\"date\">2022</span>, they found that people performing small acts of kindness underestimated the positive effect their actions had on others. &nbsp;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"92e6f5a5-e3f5-49ae-9a99-75550291de42","content":"<p>do people perceive acts of kindness<span data-ssml-say-as=\"characters\">.</span></p>"},{"id":"ac929aa5-07bc-477c-bd1d-971169f489ac","content":"<p>do people perceive acts of kindness<span data-ssml-say-as=\"characters\">?</span> &nbsp;</p>"},{"id":"3784d777-0839-43a3-9046-ac9b6c283787","content":"<p>people perceive acts of kindness<span data-ssml-say-as=\"characters\">?</span></p>"},{"id":"5841eec4-39b4-4f8e-8302-5776daa42ccd","content":"<p>people perceive acts of kindness<span data-ssml-say-as=\"characters\">.</span></p>"}],"keys":["5841eec4-39b4-4f8e-8302-5776daa42ccd"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is end-of-sentence punctuation. This choice correctly uses a period to punctuate a declarative sentence that asks an indirect question (\"Researchers Amit Kumar and Nicholas Epley investigated how people perceive acts of kindness\").</p><p>Choice A is incorrect. The structure of the sentence requires a declarative clause at the end of the sentence that states what Kumar and Epley did, not an interrogative clause that asks a direct question, such as \"how do people perceive acts of kindness.\" Choice B is incorrect. The structure of the sentence requires a declarative clause at the end of the sentence that states what Kumar and Epley did, not an interrogative clause that asks a direct question, such as \"how do people perceive acts of kindness?\" Choice C is incorrect. It&rsquo;s unconventional to use a question mark in this way to punctuate a declarative sentence that asks an indirect question, such as \"Researchers&hellip;kindness.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323049,"updateDate":1730147323049}$SATQ$::jsonb, 1730147323049, 1730147323049),
    ($SATQ$a7fdf862$SATQ$, $SATQ$2dc8fd9e-7505-4375-8f4b-a585bd6bd9a9$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Azulejos, mosaics made of glazed ceramic tiles, can be found throughout Portugal. These mosaics beautify places such as <span aria-hidden="true">______</span><span class="sr-only">blank</span> stations, and public squares. &nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"969ebc61-ad68-4f2b-bdbb-976a4296130a","content":"<p>libraries train</p>"},{"id":"e855b3cc-4b40-4754-84be-852f726fac00","content":"<p>libraries: train</p>"},{"id":"f99e57d5-a251-49e5-b9f8-e4aea781d311","content":"<p>libraries&mdash;train &nbsp;</p>"},{"id":"2ea7e075-1b61-4ad6-83aa-7f893804e690","content":"<p>libraries, train</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["2ea7e075-1b61-4ad6-83aa-7f893804e690"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the punctuation of items in a simple series. The comma after "libraries" is used conventionally to separate the first and second items ("libraries" and "train stations") in the series.</p><p>Choice A is incorrect because it fails to separate the first two items ("libraries" and "train stations") in the series. Choice B is incorrect because a colon can&rsquo;t be used in this way to separate items in a simple series. Choice C is incorrect because a dash can&rsquo;t be used in this way to separate items in a simple series.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a7fdf862","external_id":"2dc8fd9e-7505-4375-8f4b-a585bd6bd9a9","vaultid":null,"uId":"83a81689-971c-4f8b-93f2-8032f59f4316","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Azulejos, mosaics made of glazed ceramic tiles, can be found throughout Portugal. These mosaics beautify places such as <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> stations, and public squares. &nbsp;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"969ebc61-ad68-4f2b-bdbb-976a4296130a","content":"<p>libraries train</p>"},{"id":"e855b3cc-4b40-4754-84be-852f726fac00","content":"<p>libraries: train</p>"},{"id":"f99e57d5-a251-49e5-b9f8-e4aea781d311","content":"<p>libraries&mdash;train &nbsp;</p>"},{"id":"2ea7e075-1b61-4ad6-83aa-7f893804e690","content":"<p>libraries, train</p>"}],"keys":["2ea7e075-1b61-4ad6-83aa-7f893804e690"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the punctuation of items in a simple series. The comma after \"libraries\" is used conventionally to separate the first and second items (\"libraries\" and \"train stations\") in the series.</p><p>Choice A is incorrect because it fails to separate the first two items (\"libraries\" and \"train stations\") in the series. Choice B is incorrect because a colon can&rsquo;t be used in this way to separate items in a simple series. Choice C is incorrect because a dash can&rsquo;t be used in this way to separate items in a simple series.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323050,"updateDate":1730147323050}$SATQ$::jsonb, 1730147323050, 1730147323050),
    ($SATQ$a872c60a$SATQ$, $SATQ$37abd28a-364b-4181-b8f0-03137396a0f4$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>The pedagogy of the Suzuki method is rooted in several central <span aria-hidden="true">______</span><span class="sr-only">blank</span> by Japanese violinist Shinichi Suzuki, who sought to parallel the linguistic learning environment, the method emphasizes playing instruments from a very young age and teaches students as young as three to play simple classical pieces such as &ldquo;March in G.&rdquo;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"276644c8-11d2-44ec-89d3-688a23055898","content":"<p>tenets<span data-ssml-say-as=\"characters\">.</span> Developed</p>"},{"id":"54f8fe88-a4b4-43b2-bb24-02ccf31c2f7a","content":"<p>tenets developed</p>"},{"id":"5787a111-e054-4362-abff-f32ae195b0b9","content":"<p>tenets that<span data-ssml-say-as=\"characters\">,</span> developed</p>"},{"id":"e9ad0ab8-2007-44de-b6a9-5ce0df9b3910","content":"<p>tenets<span data-ssml-say-as=\"characters\">,</span> developed</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["276644c8-11d2-44ec-89d3-688a23055898"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is punctuation use between sentences. This choice correctly uses a period to mark the boundary between one sentence ("The pedagogy...tenets") and another ("Developed...&lsquo;March in G&rsquo;"). The participial phrase "developed by Japanese violinist Shinichi Suzuki" modifies the subject of the next sentence, "the method."</p><p>Choice B is incorrect because it results in a run-on sentence. The sentences ("The pedagogy...tenets" and "Developed...&lsquo;March in G&rsquo;") are fused without punctuation and/or a conjunction. Choice C is incorrect because it creates a confusing and illogical sentence structure. The relative pronoun "that" followed by a comma can&rsquo;t be used in this way to mark the boundary between sentences. Choice D is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a872c60a","external_id":"37abd28a-364b-4181-b8f0-03137396a0f4","vaultid":null,"uId":"a6c98607-30c3-4fc6-8f31-66dd41e0883f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>The pedagogy of the Suzuki method is rooted in several central <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> by Japanese violinist Shinichi Suzuki, who sought to parallel the linguistic learning environment, the method emphasizes playing instruments from a very young age and teaches students as young as three to play simple classical pieces such as &ldquo;March in G.&rdquo;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"276644c8-11d2-44ec-89d3-688a23055898","content":"<p>tenets<span data-ssml-say-as=\"characters\">.</span> Developed</p>"},{"id":"54f8fe88-a4b4-43b2-bb24-02ccf31c2f7a","content":"<p>tenets developed</p>"},{"id":"5787a111-e054-4362-abff-f32ae195b0b9","content":"<p>tenets that<span data-ssml-say-as=\"characters\">,</span> developed</p>"},{"id":"e9ad0ab8-2007-44de-b6a9-5ce0df9b3910","content":"<p>tenets<span data-ssml-say-as=\"characters\">,</span> developed</p>"}],"keys":["276644c8-11d2-44ec-89d3-688a23055898"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is punctuation use between sentences. This choice correctly uses a period to mark the boundary between one sentence (\"The pedagogy...tenets\") and another (\"Developed...&lsquo;March in G&rsquo;\"). The participial phrase \"developed by Japanese violinist Shinichi Suzuki\" modifies the subject of the next sentence, \"the method.\"</p><p>Choice B is incorrect because it results in a run-on sentence. The sentences (\"The pedagogy...tenets\" and \"Developed...&lsquo;March in G&rsquo;\") are fused without punctuation and/or a conjunction. Choice C is incorrect because it creates a confusing and illogical sentence structure. The relative pronoun \"that\" followed by a comma can&rsquo;t be used in this way to mark the boundary between sentences. Choice D is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061177,"updateDate":1755117061177}$SATQ$::jsonb, 1755117061177, 1755117061177),
    ($SATQ$a8fa749a$SATQ$, $SATQ$fe470995-4b5b-4316-86cc-b2a363cc3737$SATQ$::uuid, $SATQ$d518bd3d-783f-44d5-83ee-e190fd6ad64b$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Nigerian author Buchi Emecheta&rsquo;s celebrated literary oeuvre includes <em>The Joys of Motherhood</em>, a novel about the changing roles of women in 1950s <span aria-hidden="true">______</span><span class="sr-only">blank</span> a television play about the private struggles of a newlywed couple in Nigeria; and <em>Head Above Water</em>, her autobiography.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"0922562f-1507-4db3-91ee-b265e0ac323f","content":"<p>Lagos, <em>A Kind of Marriage</em>,</p>"},{"id":"17e8988c-8858-4186-9bc7-b4a526a6c3c9","content":"<p>Lagos; <em>A Kind of Marriage</em>,</p>"},{"id":"2b80f389-5395-4977-8490-b05c9b768bfc","content":"<p>Lagos, <em>A Kind of Marriage</em>:</p>"},{"id":"e709a8a6-46cc-4258-96c7-ca4976677944","content":"<p>Lagos; <em>A Kind of Marriage</em></p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["17e8988c-8858-4186-9bc7-b4a526a6c3c9"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the punctuation of items in a complex series (a series including internal punctuation). In this choice, the semicolon after &ldquo;Lagos&rdquo; is conventionally used to separate the first item (&ldquo;<em>The Joys</em>&hellip;Lagos&rdquo;) and the second item (&ldquo;<em>A Kind</em>&hellip;Nigeria&rdquo;) in the series. Further, the comma after &ldquo;<em>Marriage</em>&rdquo; correctly separates the title &ldquo;<em>A Kind of Marriage</em>&rdquo; from the supplementary phrase (&ldquo;a television&hellip;Nigeria&rdquo;) that describes it. </p><p>Choice A is incorrect because the comma after &ldquo;Lagos&rdquo; doesn&rsquo;t match the semicolon used later in the series to separate the second item (&ldquo;<em>A Kind</em>&hellip;Nigeria&rdquo;) from the third item (&ldquo;and&hellip;autobiography&rdquo;). Choice C is incorrect because the comma after &ldquo;Lagos&rdquo; doesn&rsquo;t match the semicolon used later in the series to separate the second item (&ldquo;<em>A Kind</em>&hellip;Nigeria&rdquo;) from the third item (&ldquo;and&hellip;autobiography&rdquo;). Additionally, a colon can&rsquo;t be used in this way to separate the title &ldquo;<em>A Kind of Marriage</em>&rdquo; from the supplementary phrase (&ldquo;a television&hellip;Nigeria&rdquo;) that describes it. Choice D is incorrect because it fails to use appropriate punctuation to separate the title &ldquo;<em>A Kind of Marriage</em>&rdquo; from the supplementary phrase (&ldquo;a television&hellip;Nigeria&rdquo;) that describes it. </p>$SATQ$, false, 0, $SATQ$OSP-692-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$7f5ef976-a520-425e-ab5c-f943c32284b2$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"a8fa749a","external_id":"fe470995-4b5b-4316-86cc-b2a363cc3737","vaultid":"d518bd3d-783f-44d5-83ee-e190fd6ad64b","uId":"8f8cf586-5d13-49f1-bea0-66c56b604d68","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Nigerian author Buchi Emecheta&rsquo;s celebrated literary oeuvre includes <em>The Joys of Motherhood</em>, a novel about the changing roles of women in 1950s <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> a television play about the private struggles of a newlywed couple in Nigeria; and <em>Head Above Water</em>, her autobiography.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"0922562f-1507-4db3-91ee-b265e0ac323f","content":"<p>Lagos, <em>A Kind of Marriage</em>,</p>"},{"id":"17e8988c-8858-4186-9bc7-b4a526a6c3c9","content":"<p>Lagos; <em>A Kind of Marriage</em>,</p>"},{"id":"2b80f389-5395-4977-8490-b05c9b768bfc","content":"<p>Lagos, <em>A Kind of Marriage</em>:</p>"},{"id":"e709a8a6-46cc-4258-96c7-ca4976677944","content":"<p>Lagos; <em>A Kind of Marriage</em></p>"}],"keys":["17e8988c-8858-4186-9bc7-b4a526a6c3c9"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is the punctuation of items in a complex series (a series including internal punctuation). In this choice, the semicolon after &ldquo;Lagos&rdquo; is conventionally used to separate the first item (&ldquo;<em>The Joys</em>&hellip;Lagos&rdquo;) and the second item (&ldquo;<em>A Kind</em>&hellip;Nigeria&rdquo;) in the series. Further, the comma after &ldquo;<em>Marriage</em>&rdquo; correctly separates the title &ldquo;<em>A Kind of Marriage</em>&rdquo; from the supplementary phrase (&ldquo;a television&hellip;Nigeria&rdquo;) that describes it. </p><p>Choice A is incorrect because the comma after &ldquo;Lagos&rdquo; doesn&rsquo;t match the semicolon used later in the series to separate the second item (&ldquo;<em>A Kind</em>&hellip;Nigeria&rdquo;) from the third item (&ldquo;and&hellip;autobiography&rdquo;). Choice C is incorrect because the comma after &ldquo;Lagos&rdquo; doesn&rsquo;t match the semicolon used later in the series to separate the second item (&ldquo;<em>A Kind</em>&hellip;Nigeria&rdquo;) from the third item (&ldquo;and&hellip;autobiography&rdquo;). Additionally, a colon can&rsquo;t be used in this way to separate the title &ldquo;<em>A Kind of Marriage</em>&rdquo; from the supplementary phrase (&ldquo;a television&hellip;Nigeria&rdquo;) that describes it. Choice D is incorrect because it fails to use appropriate punctuation to separate the title &ldquo;<em>A Kind of Marriage</em>&rdquo; from the supplementary phrase (&ldquo;a television&hellip;Nigeria&rdquo;) that describes it. </p>","parenttemplatename":"OSP-692-SEC","parenttemplateid":"","templateclusterid":"7f5ef976-a520-425e-ab5c-f943c32284b2","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959346,"updateDate":1691007959346}$SATQ$::jsonb, 1691007959346, 1691007959346),
    ($SATQ$a94b7fd6$SATQ$, $SATQ$b64f1285-2a18-40a7-ae6b-1eedba20c77e$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>With residents from Mexico, China, El Salvador, and many other countries, Los Angeles has long been a city of cultural diversity. Even back in the 1860s, nearly 30% of the city&rsquo;s population <span aria-hidden="true">______</span><span class="sr-only">blank</span> from outside the United States.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"c1772eb2-64b0-4ffb-b9f5-a0c64dab5780","content":"<p>is being</p>"},{"id":"97b84fbd-ea90-408c-b3d5-dbcf447cfdcf","content":"<p>was</p>"},{"id":"6ffd5077-d93c-406a-bb51-a07ad544be6b","content":"<p>is</p>"},{"id":"f7204749-1070-4473-a616-bcfb6191e241","content":"<p>will be</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["97b84fbd-ea90-408c-b3d5-dbcf447cfdcf"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the past tense verb "was," used in conjunction with the prepositional phrase "from outside the United States," correctly indicates that in the 1860s nearly 30% of the population in Los Angeles wasn&rsquo;t from the US.</p><p>Choice A is incorrect because the present progressive tense verb "is being" doesn&rsquo;t indicate that the claim about Los Angeles&rsquo;s population refers to the population back in the 1860s. Choice C is incorrect because the present tense verb "is" doesn&rsquo;t indicate that the claim about Los Angeles&rsquo;s population refers to the population back in the 1860s. Choice D is incorrect because the future tense verb "will be" doesn&rsquo;t indicate that the claim about Los Angeles&rsquo;s population refers to the population back in the 1860s.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"a94b7fd6","external_id":"b64f1285-2a18-40a7-ae6b-1eedba20c77e","vaultid":null,"uId":"7576aeaa-9481-4ebd-81f3-db7da0789e21","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>With residents from Mexico, China, El Salvador, and many other countries, Los Angeles has long been a city of cultural diversity. Even back in the 1860s, nearly 30% of the city&rsquo;s population <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> from outside the United States.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"c1772eb2-64b0-4ffb-b9f5-a0c64dab5780","content":"<p>is being</p>"},{"id":"97b84fbd-ea90-408c-b3d5-dbcf447cfdcf","content":"<p>was</p>"},{"id":"6ffd5077-d93c-406a-bb51-a07ad544be6b","content":"<p>is</p>"},{"id":"f7204749-1070-4473-a616-bcfb6191e241","content":"<p>will be</p>"}],"keys":["97b84fbd-ea90-408c-b3d5-dbcf447cfdcf"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the past tense verb \"was,\" used in conjunction with the prepositional phrase \"from outside the United States,\" correctly indicates that in the 1860s nearly 30% of the population in Los Angeles wasn&rsquo;t from the US.</p><p>Choice A is incorrect because the present progressive tense verb \"is being\" doesn&rsquo;t indicate that the claim about Los Angeles&rsquo;s population refers to the population back in the 1860s. Choice C is incorrect because the present tense verb \"is\" doesn&rsquo;t indicate that the claim about Los Angeles&rsquo;s population refers to the population back in the 1860s. Choice D is incorrect because the future tense verb \"will be\" doesn&rsquo;t indicate that the claim about Los Angeles&rsquo;s population refers to the population back in the 1860s.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323050,"updateDate":1730147323050}$SATQ$::jsonb, 1730147323050, 1730147323050),
    ($SATQ$a9e5b788$SATQ$, $SATQ$c1511bfa-bdff-47a6-946b-2041f9cdb4d7$SATQ$::uuid, $SATQ$e53007cc-525c-4073-aeeb-34f10519ef8e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>In discussing Mary Shelley&rsquo;s 1818 epistolary novel <em>Frankenstein</em>, literary theorist Gayatri Spivak directs the reader&rsquo;s attention to the character of Margaret Saville. As Spivak points out, Saville is not the protagonist of Shelley&rsquo;s <span aria-hidden="true">______</span><span class="sr-only">blank</span> as the recipient of the letters that frame the book&rsquo;s narrative, she&rsquo;s the &ldquo;occasion&rdquo; of it.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"d2d100c7-259c-403e-bcf0-25c8952367e7","content":"<p>novel</p>"},{"id":"793881fb-1dbe-4da7-98c2-1bc85596d2cd","content":"<p>novel,</p>"},{"id":"de34f422-8ee8-4445-a7db-080e3a4388d1","content":"<p>novel; rather,</p>"},{"id":"b104f920-44cc-4a9d-9065-be424aace2a3","content":"<p>novel, rather,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["de34f422-8ee8-4445-a7db-080e3a4388d1"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice correctly uses a semicolon to join a main clause (&ldquo;Saville...novel&rdquo;) and a second main clause (&ldquo;she&rsquo;s...it&rdquo;) preceded by supplementary elements (&ldquo;rather...narrative&rdquo;). </p><p>Choice A is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction. Choice B is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join two main clauses. Choice D is incorrect because it results in a comma splice. Without a conjunction following it, the comma after &ldquo;novel&rdquo; can&rsquo;t be used in this way to join the two main clauses. </p>$SATQ$, false, 0, $SATQ$OSP-KA-BOU-H002$SATQ$, $SATQ$$SATQ$, $SATQ$9089fe57-1cc3-43b7-951d-276627f26ce9$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"a9e5b788","external_id":"c1511bfa-bdff-47a6-946b-2041f9cdb4d7","vaultid":"e53007cc-525c-4073-aeeb-34f10519ef8e","uId":"3c604013-84e6-4b71-828f-f7feb0e3db43","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>In discussing Mary Shelley&rsquo;s 1818 epistolary novel <em>Frankenstein</em>, literary theorist Gayatri Spivak directs the reader&rsquo;s attention to the character of Margaret Saville. As Spivak points out, Saville is not the protagonist of Shelley&rsquo;s <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> as the recipient of the letters that frame the book&rsquo;s narrative, she&rsquo;s the &ldquo;occasion&rdquo; of it.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"d2d100c7-259c-403e-bcf0-25c8952367e7","content":"<p>novel</p>"},{"id":"793881fb-1dbe-4da7-98c2-1bc85596d2cd","content":"<p>novel,</p>"},{"id":"de34f422-8ee8-4445-a7db-080e3a4388d1","content":"<p>novel; rather,</p>"},{"id":"b104f920-44cc-4a9d-9065-be424aace2a3","content":"<p>novel, rather,</p>"}],"keys":["de34f422-8ee8-4445-a7db-080e3a4388d1"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice correctly uses a semicolon to join a main clause (&ldquo;Saville...novel&rdquo;) and a second main clause (&ldquo;she&rsquo;s...it&rdquo;) preceded by supplementary elements (&ldquo;rather...narrative&rdquo;). </p><p>Choice A is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction. Choice B is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join two main clauses. Choice D is incorrect because it results in a comma splice. Without a conjunction following it, the comma after &ldquo;novel&rdquo; can&rsquo;t be used in this way to join the two main clauses. </p>","parenttemplatename":"OSP-KA-BOU-H002","parenttemplateid":"","templateclusterid":"9089fe57-1cc3-43b7-951d-276627f26ce9","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959358,"updateDate":1691007959358}$SATQ$::jsonb, 1691007959358, 1691007959358),
    ($SATQ$aa443c4b$SATQ$, $SATQ$f731e445-687b-4511-98de-b2b5fcfe6f9b$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Recent pollen analyses of the Aran Islands have led some researchers to propose that the now treeless islands were once wooded. This hypothesis <span aria-hidden="true">______</span><span class="sr-only">blank</span> that certain trees, such as <em><span data-ssml-sub-alias="P">P.</span> sylvestris</em>, survived without interruption or human intervention throughout the Holocene cannot stand, researchers Michael O&rsquo;Connell and Karen Molloy counter, unless other explanations can first be ruled out.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"ccbeb693-fdbb-4d38-bc91-5a7ce2d7e18c","content":"<p>suggesting</p>"},{"id":"58ac6344-7c92-4da8-82ff-eb38ed1bd807","content":"<p>suggested</p>"},{"id":"a4a2d241-9dad-4e52-9a35-c4058cb77543","content":"<p>suggests</p>"},{"id":"d900eec3-2aea-48b9-b05e-f1e37d676a06","content":"<p>has suggested</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["ccbeb693-fdbb-4d38-bc91-5a7ce2d7e18c"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite present participle "suggesting" is correctly used to form a restrictive participial phrase ("suggesting...Holocene") within the main clause ("This hypothesis...cannot stand..."). This participial phrase functions as part of the sentence&rsquo;s subject ("This...Holocene"), providing essential identifying information about what the hypothesis states&mdash;namely, that certain trees survived without interruption or human intervention throughout the Holocene.</p><p>Choice B is incorrect because it results in an ungrammatical sentence. The finite verb "suggested" can&rsquo;t be used in this way within the subject of the sentence. Choice C is incorrect because it results in an ungrammatical sentence. The finite verb "suggests" can&rsquo;t be used in this way within the subject of the sentence. Choice D is incorrect because it results in an ungrammatical sentence. The finite verb "has suggested" can&rsquo;t be used in this way within the subject of the sentence.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"aa443c4b","external_id":"f731e445-687b-4511-98de-b2b5fcfe6f9b","vaultid":null,"uId":"c92089b0-d5f1-44db-ac7a-84a8baa19940","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Recent pollen analyses of the Aran Islands have led some researchers to propose that the now treeless islands were once wooded. This hypothesis <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> that certain trees, such as <em><span data-ssml-sub-alias=\"P\">P.</span> sylvestris</em>, survived without interruption or human intervention throughout the Holocene cannot stand, researchers Michael O&rsquo;Connell and Karen Molloy counter, unless other explanations can first be ruled out.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"ccbeb693-fdbb-4d38-bc91-5a7ce2d7e18c","content":"<p>suggesting</p>"},{"id":"58ac6344-7c92-4da8-82ff-eb38ed1bd807","content":"<p>suggested</p>"},{"id":"a4a2d241-9dad-4e52-9a35-c4058cb77543","content":"<p>suggests</p>"},{"id":"d900eec3-2aea-48b9-b05e-f1e37d676a06","content":"<p>has suggested</p>"}],"keys":["ccbeb693-fdbb-4d38-bc91-5a7ce2d7e18c"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite present participle \"suggesting\" is correctly used to form a restrictive participial phrase (\"suggesting...Holocene\") within the main clause (\"This hypothesis...cannot stand...\"). This participial phrase functions as part of the sentence&rsquo;s subject (\"This...Holocene\"), providing essential identifying information about what the hypothesis states&mdash;namely, that certain trees survived without interruption or human intervention throughout the Holocene.</p><p>Choice B is incorrect because it results in an ungrammatical sentence. The finite verb \"suggested\" can&rsquo;t be used in this way within the subject of the sentence. Choice C is incorrect because it results in an ungrammatical sentence. The finite verb \"suggests\" can&rsquo;t be used in this way within the subject of the sentence. Choice D is incorrect because it results in an ungrammatical sentence. The finite verb \"has suggested\" can&rsquo;t be used in this way within the subject of the sentence.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669215,"updateDate":1743430669215}$SATQ$::jsonb, 1743430669215, 1743430669215),
    ($SATQ$aaa1907f$SATQ$, $SATQ$ddf2d37c-18bd-4bb1-bedf-9a2f4de6b4e4$SATQ$::uuid, $SATQ$df5a6b96-8c5a-4125-a942-28cff137ebea$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>To serve local families during the Great Depression, innovative New York City librarian Pura Belpr&eacute; offered storytelling in both English and Spanish, an uncommon <span aria-hidden="true">______</span><span class="sr-only">blank</span> celebrated <em>el D&iacute;a de los Tres Reyes Magos</em>,<em> </em>an important community holiday; and put on puppet shows dramatizing Puerto Rican folktales.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"dfddf6ee-b014-4eb3-a820-a954d1abfb07","content":"<p>practice, at the time</p>"},{"id":"b605e3d1-9d80-421a-8e4a-5832f8f02f73","content":"<p>practice at the time;</p>"},{"id":"c114e903-b081-4add-a5a3-a233d0a3a224","content":"<p>practice, at the time,</p>"},{"id":"483e912b-5312-4224-af94-dff79c10fbf1","content":"<p>practice at the time,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["b605e3d1-9d80-421a-8e4a-5832f8f02f73"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the punctuation of elements in a complex series. It&rsquo;s conventional to use a semicolon to separate items in a complex series with internal punctuation, and in this choice, the semicolon after "time" is conventionally used to separate the first item ("offered&hellip;time") and the second ("celebrated&hellip;holiday") in the series of activities that librarian Pura Belpr&eacute; offered. Moreover, the semicolon after "time" matches the semicolon used later to separate the second item ("celebrated...holiday") and the third ("and...folktales") in the series.</p><p>Choice A is incorrect because it fails to use appropriate punctuation to separate the first item and the second item in the complex series. Furthermore, a comma isn&rsquo;t needed between the noun "practice" and the prepositional phrase "at the time" because the prepositional phrase is essential to the full meaning of the phrase "an uncommon practice at the time." Choice C is incorrect because a comma after "time" doesn&rsquo;t match the semicolon used later to separate the second ("celebrated...holiday") and third ("and...folktales") items in the series. Furthermore, a comma isn&rsquo;t needed between the noun "practice" and the prepositional phrase "at the time" because the prepositional phrase is essential to the full meaning of the phrase "an uncommon practice at the time." Choice D is incorrect because a comma after "time" doesn&rsquo;t match the semicolon used later to separate the second ("celebrated...holiday") and third ("and...folktales") items in the series.</p>$SATQ$, false, 0, $SATQ$OSP-795-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$c76a3c6c-a1fa-41a7-acd1-ad46a7242720$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"aaa1907f","external_id":"ddf2d37c-18bd-4bb1-bedf-9a2f4de6b4e4","vaultid":"df5a6b96-8c5a-4125-a942-28cff137ebea","uId":"12d18b56-8e4b-4454-8f18-6f82e4c55ef4","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>To serve local families during the Great Depression, innovative New York City librarian Pura Belpr&eacute; offered storytelling in both English and Spanish, an uncommon <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> celebrated <em>el D&iacute;a de los Tres Reyes Magos</em>,<em> </em>an important community holiday; and put on puppet shows dramatizing Puerto Rican folktales.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"dfddf6ee-b014-4eb3-a820-a954d1abfb07","content":"<p>practice, at the time</p>"},{"id":"b605e3d1-9d80-421a-8e4a-5832f8f02f73","content":"<p>practice at the time;</p>"},{"id":"c114e903-b081-4add-a5a3-a233d0a3a224","content":"<p>practice, at the time,</p>"},{"id":"483e912b-5312-4224-af94-dff79c10fbf1","content":"<p>practice at the time,</p>"}],"keys":["b605e3d1-9d80-421a-8e4a-5832f8f02f73"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is the punctuation of elements in a complex series. It&rsquo;s conventional to use a semicolon to separate items in a complex series with internal punctuation, and in this choice, the semicolon after \"time\" is conventionally used to separate the first item (\"offered&hellip;time\") and the second (\"celebrated&hellip;holiday\") in the series of activities that librarian Pura Belpr&eacute; offered. Moreover, the semicolon after \"time\" matches the semicolon used later to separate the second item (\"celebrated...holiday\") and the third (\"and...folktales\") in the series.</p><p>Choice A is incorrect because it fails to use appropriate punctuation to separate the first item and the second item in the complex series. Furthermore, a comma isn&rsquo;t needed between the noun \"practice\" and the prepositional phrase \"at the time\" because the prepositional phrase is essential to the full meaning of the phrase \"an uncommon practice at the time.\" Choice C is incorrect because a comma after \"time\" doesn&rsquo;t match the semicolon used later to separate the second (\"celebrated...holiday\") and third (\"and...folktales\") items in the series. Furthermore, a comma isn&rsquo;t needed between the noun \"practice\" and the prepositional phrase \"at the time\" because the prepositional phrase is essential to the full meaning of the phrase \"an uncommon practice at the time.\" Choice D is incorrect because a comma after \"time\" doesn&rsquo;t match the semicolon used later to separate the second (\"celebrated...holiday\") and third (\"and...folktales\") items in the series.</p>","parenttemplatename":"OSP-795-SEC","parenttemplateid":"","templateclusterid":"c76a3c6c-a1fa-41a7-acd1-ad46a7242720","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959353,"updateDate":1691007959353}$SATQ$::jsonb, 1691007959353, 1691007959353),
    ($SATQ$aab74a3b$SATQ$, $SATQ$b3394e1d-8bef-4690-96df-747d1268c0fe$SATQ$::uuid, $SATQ$c449aa26-2ed2-478b-9e11-94751bc91156$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Researcher Lin Zhi developed a process for increasing the tensile strength&mdash;measured in gigapascals, or GPa&mdash;of silkworm <span aria-hidden="true">______</span><span class="sr-only">blank</span> dissolving and reweaving the silk in a solution of iron metal ions, zinc, and sugar, Zhi increased the amount of force required to stretch it from approximately 0.5 GPa to 2 GPa.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"921d1a9d-34fc-4293-ab1f-b7c66e29b260","content":"<p>silk, by</p>"},{"id":"25ff0437-b6ba-4760-a9db-a060394a04a4","content":"<p>silk by</p>"},{"id":"9ac99ea3-e4b5-4b93-a71f-babe4d5a56f3","content":"<p>silk and by</p>"},{"id":"85d25a72-93f7-4d46-a287-1c29bac97d3b","content":"<p>silk. By</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["85d25a72-93f7-4d46-a287-1c29bac97d3b"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The independent clauses "researcher Lin Zhi&hellip;silk" and "by dissolving&hellip;2 GPa" can be grammatically separated by a period. They can stand alone as sentences, and this is the only choice that lets them do that.</p><p>Choice A is incorrect. This choice results in a grammar error called a comma splice. "Researcher Lin Zhi&hellip;silk" and "by dissolving&hellip;2 GPa" are both independent clauses. They need to either be separated with punctuation like a period or a semicolon, or they need to be connected by a comma and a coordinating conjunction like "and." A comma alone isn&rsquo;t enough. Choice B is incorrect. This choice results in a grammar error called a run-on sentence. "Researcher Lin Zhi&hellip;silk" and "by dissolving&hellip;2 GPa" are both independent clauses. They need to either be separated with punctuation like a period or a semicolon, or they need to be connected by a comma and a coordinating conjunction like "and." Choice C is incorrect. This choice results in a grammar error called a run-on sentence. "Researcher Lin Zhi&hellip;silk" and "by dissolving&hellip;2 GPa" are both independent clauses. The coordinating conjunction "and" isn&rsquo;t enough to link them by itself. We need a comma, too.</p>$SATQ$, false, 0, $SATQ$OSP-KA-BOU-H009$SATQ$, $SATQ$$SATQ$, $SATQ$931b3fa8-18e2-40ea-9c36-bbd427d01bff$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"aab74a3b","external_id":"b3394e1d-8bef-4690-96df-747d1268c0fe","vaultid":"c449aa26-2ed2-478b-9e11-94751bc91156","uId":"34bdcc13-e94f-401a-a79f-59433fdbea3d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Researcher Lin Zhi developed a process for increasing the tensile strength&mdash;measured in gigapascals, or GPa&mdash;of silkworm <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> dissolving and reweaving the silk in a solution of iron metal ions, zinc, and sugar, Zhi increased the amount of force required to stretch it from approximately 0.5 GPa to 2 GPa.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"921d1a9d-34fc-4293-ab1f-b7c66e29b260","content":"<p>silk, by</p>"},{"id":"25ff0437-b6ba-4760-a9db-a060394a04a4","content":"<p>silk by</p>"},{"id":"9ac99ea3-e4b5-4b93-a71f-babe4d5a56f3","content":"<p>silk and by</p>"},{"id":"85d25a72-93f7-4d46-a287-1c29bac97d3b","content":"<p>silk. By</p>"}],"keys":["85d25a72-93f7-4d46-a287-1c29bac97d3b"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The independent clauses \"researcher Lin Zhi&hellip;silk\" and \"by dissolving&hellip;2 GPa\" can be grammatically separated by a period. They can stand alone as sentences, and this is the only choice that lets them do that.</p><p>Choice A is incorrect. This choice results in a grammar error called a comma splice. \"Researcher Lin Zhi&hellip;silk\" and \"by dissolving&hellip;2 GPa\" are both independent clauses. They need to either be separated with punctuation like a period or a semicolon, or they need to be connected by a comma and a coordinating conjunction like \"and.\" A comma alone isn&rsquo;t enough. Choice B is incorrect. This choice results in a grammar error called a run-on sentence. \"Researcher Lin Zhi&hellip;silk\" and \"by dissolving&hellip;2 GPa\" are both independent clauses. They need to either be separated with punctuation like a period or a semicolon, or they need to be connected by a comma and a coordinating conjunction like \"and.\" Choice C is incorrect. This choice results in a grammar error called a run-on sentence. \"Researcher Lin Zhi&hellip;silk\" and \"by dissolving&hellip;2 GPa\" are both independent clauses. The coordinating conjunction \"and\" isn&rsquo;t enough to link them by itself. We need a comma, too.</p>","parenttemplatename":"OSP-KA-BOU-H009","parenttemplateid":"","templateclusterid":"931b3fa8-18e2-40ea-9c36-bbd427d01bff","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959359,"updateDate":1691007959359}$SATQ$::jsonb, 1691007959359, 1691007959359),
    ($SATQ$aab78b25$SATQ$, $SATQ$3491d680-a522-4abf-8b49-9f6d917bef8b$SATQ$::uuid, $SATQ$ef631535-a29c-4d9c-96e0-2424e6a56b1b$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Psychophysicist Howard Moskowitz was hired by a soda company to determine how much artificial sweetener <span aria-hidden="true">______</span><span class="sr-only">blank</span> After conducting consumer taste tests, he found that no such ideal existed: participants expressed a wide range of preferences for different blends of sweetener, carbonization, and flavoring.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"c5518fb4-3d33-409e-9dab-d437d7a90c08","content":"<p>do most people prefer in a diet drink?&nbsp;</p>"},{"id":"a275069a-6944-43d7-bb16-c09d07a55392","content":"<p>do most people prefer in a diet drink.</p>"},{"id":"70ce8f17-f8d7-44aa-bf3f-db77e60fc853","content":"<p>most people prefer in a diet drink?</p>"},{"id":"8ee3ec87-771e-4532-8036-93ddb3c6f9b6","content":"<p>most people prefer in a diet drink.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["8ee3ec87-771e-4532-8036-93ddb3c6f9b6"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. This sentence is a statement: &ldquo;Moskowitz was hired by a soda company to determine how much artificial sweetener most people prefer in a diet drink.&rdquo; So a period is the most appropriate punctuation mark. &nbsp;</p><p>Choice A is incorrect. This doesn&rsquo;t complete the text in a way that conforms to the conventions of Standard English. This sentence is not a question&mdash;it&rsquo;s a statement. So a question mark is not the appropriate punctuation.&nbsp;Choice B is incorrect. This doesn&rsquo;t complete the text in a way that conforms to the conventions of Standard English. We already have the verbs &ldquo;was hired&hellip;to determine&rdquo; in this sentence. The verb &ldquo;do&rdquo; is not needed and results in a confusing, ungrammatical sentence.&nbsp;Choice C is incorrect. This doesn&rsquo;t complete the text in a way that conforms to the conventions of Standard English. This sentence is not a question&mdash;it&rsquo;s a statement. So a question mark is not the appropriate punctuation.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-603-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$7f608682-0b86-4090-9787-952b8beda2c0$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"aab78b25","external_id":"3491d680-a522-4abf-8b49-9f6d917bef8b","vaultid":"ef631535-a29c-4d9c-96e0-2424e6a56b1b","uId":"4af994ee-4840-466c-b765-94914c5861c6","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Psychophysicist Howard Moskowitz was hired by a soda company to determine how much artificial sweetener <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> After conducting consumer taste tests, he found that no such ideal existed: participants expressed a wide range of preferences for different blends of sweetener, carbonization, and flavoring.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"c5518fb4-3d33-409e-9dab-d437d7a90c08","content":"<p>do most people prefer in a diet drink?&nbsp;</p>"},{"id":"a275069a-6944-43d7-bb16-c09d07a55392","content":"<p>do most people prefer in a diet drink.</p>"},{"id":"70ce8f17-f8d7-44aa-bf3f-db77e60fc853","content":"<p>most people prefer in a diet drink?</p>"},{"id":"8ee3ec87-771e-4532-8036-93ddb3c6f9b6","content":"<p>most people prefer in a diet drink.</p>"}],"keys":["8ee3ec87-771e-4532-8036-93ddb3c6f9b6"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. This sentence is a statement: &ldquo;Moskowitz was hired by a soda company to determine how much artificial sweetener most people prefer in a diet drink.&rdquo; So a period is the most appropriate punctuation mark. &nbsp;</p><p>Choice A is incorrect. This doesn&rsquo;t complete the text in a way that conforms to the conventions of Standard English. This sentence is not a question&mdash;it&rsquo;s a statement. So a question mark is not the appropriate punctuation.&nbsp;Choice B is incorrect. This doesn&rsquo;t complete the text in a way that conforms to the conventions of Standard English. We already have the verbs &ldquo;was hired&hellip;to determine&rdquo; in this sentence. The verb &ldquo;do&rdquo; is not needed and results in a confusing, ungrammatical sentence.&nbsp;Choice C is incorrect. This doesn&rsquo;t complete the text in a way that conforms to the conventions of Standard English. This sentence is not a question&mdash;it&rsquo;s a statement. So a question mark is not the appropriate punctuation.&nbsp;</p>","parenttemplatename":"OSP-603-SEC","parenttemplateid":"","templateclusterid":"7f608682-0b86-4090-9787-952b8beda2c0","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959338,"updateDate":1691007959338}$SATQ$::jsonb, 1691007959338, 1691007959338),
    ($SATQ$ac5536c1$SATQ$, $SATQ$007dd895-e4ed-4aa1-8414-06c33e6fd271$SATQ$::uuid, $SATQ$749a3504-7fae-43f1-9963-caccf73b355d$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Beatrix Potter is perhaps best known for writing and illustrating children&rsquo;s books such as <em>The Tale of Peter Rabbit </em>(1902), but she also dedicated herself to mycology, the study of <span aria-hidden="true">______</span><span class="sr-only">blank</span> more than 350 paintings of the fungal species she observed in nature and submitting her research on spore germination to the Linnean Society of London.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"76cc22c3-0c5d-4b71-9fca-a96b43ba9f0e","content":"<p>fungi; producing</p>"},{"id":"9c75e409-a74a-43b8-a9e0-096173466f48","content":"<p>fungi. Producing</p>"},{"id":"cdfd5690-0145-4719-b217-89e563f48107","content":"<p>fungi producing</p>"},{"id":"d9019bc7-5a1d-4b8a-ab55-a5193c2bf689","content":"<p>fungi, producing</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["d9019bc7-5a1d-4b8a-ab55-a5193c2bf689"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is punctuation use between two supplementary phrases following the coordinate clause (&ldquo;but she&hellip;mycology&rdquo;). This choice correctly uses a comma to mark the boundary between the supplementary noun phrase (&ldquo;the study of fungi&rdquo;) that defines the term &ldquo;mycology&rdquo; and the supplementary participial phrase (&ldquo;producing...London&rdquo;) that provides additional information about the extent to which Potter dedicated herself to mycology. </p><p>Choice A is incorrect because a semicolon can&rsquo;t be used in this way to join two supplementary phrases following a coordinate clause. Choice B is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with &ldquo;producing.&rdquo; Choice C is incorrect. The lack of punctuation results in a sentence that illogically suggests that the study of fungi is producing more than 350 paintings. </p>$SATQ$, false, 0, $SATQ$OSP-660-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$ae4f537d-7301-4941-b32c-61d8e3441368$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"ac5536c1","external_id":"007dd895-e4ed-4aa1-8414-06c33e6fd271","vaultid":"749a3504-7fae-43f1-9963-caccf73b355d","uId":"28491f7c-4477-458c-8a91-cf55eadc0da0","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Beatrix Potter is perhaps best known for writing and illustrating children&rsquo;s books such as <em>The Tale of Peter Rabbit </em>(1902), but she also dedicated herself to mycology, the study of <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> more than 350 paintings of the fungal species she observed in nature and submitting her research on spore germination to the Linnean Society of London.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"76cc22c3-0c5d-4b71-9fca-a96b43ba9f0e","content":"<p>fungi; producing</p>"},{"id":"9c75e409-a74a-43b8-a9e0-096173466f48","content":"<p>fungi. Producing</p>"},{"id":"cdfd5690-0145-4719-b217-89e563f48107","content":"<p>fungi producing</p>"},{"id":"d9019bc7-5a1d-4b8a-ab55-a5193c2bf689","content":"<p>fungi, producing</p>"}],"keys":["d9019bc7-5a1d-4b8a-ab55-a5193c2bf689"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is punctuation use between two supplementary phrases following the coordinate clause (&ldquo;but she&hellip;mycology&rdquo;). This choice correctly uses a comma to mark the boundary between the supplementary noun phrase (&ldquo;the study of fungi&rdquo;) that defines the term &ldquo;mycology&rdquo; and the supplementary participial phrase (&ldquo;producing...London&rdquo;) that provides additional information about the extent to which Potter dedicated herself to mycology. </p><p>Choice A is incorrect because a semicolon can&rsquo;t be used in this way to join two supplementary phrases following a coordinate clause. Choice B is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with &ldquo;producing.&rdquo; Choice C is incorrect. The lack of punctuation results in a sentence that illogically suggests that the study of fungi is producing more than 350 paintings. </p>","parenttemplatename":"OSP-660-SEC","parenttemplateid":"","templateclusterid":"ae4f537d-7301-4941-b32c-61d8e3441368","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959341,"updateDate":1691007959341}$SATQ$::jsonb, 1691007959341, 1691007959341),
    ($SATQ$ac7b8d04$SATQ$, $SATQ$324fda2b-53dc-49f4-bd65-fd0a18a3b71c$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Tracy Fullerton&rsquo;s <em>Walden, a game</em>, an unlikely fusion of the writings of nineteenth-century transcendentalist Henry David Thoreau with today&rsquo;s open-world video games, <span aria-hidden="true">______</span><span class="sr-only">blank</span> players to explore a digital version of Walden Pond, the idyllic natural setting featured in Thoreau&rsquo;s book <em>Walden</em>.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"ecac84ae-1f84-40c5-b8f5-3d777f2f5f66","content":"<p>invites</p>"},{"id":"0f01ead9-362b-48b0-be9c-d5fbabb9b37b","content":"<p>invite</p>"},{"id":"9cacaaad-ce86-4317-8aba-b8c1c4fc7f61","content":"<p>are inviting</p>"},{"id":"70378c05-36e1-41da-a508-2762b2494bfb","content":"<p>have invited</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["ecac84ae-1f84-40c5-b8f5-3d777f2f5f66"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is subject-verb agreement. The singular verb &ldquo;invites&rdquo; agrees in number with the singular subject &ldquo;Tracy Fullerton&rsquo;s <em>Walden, a game</em>.&rdquo;</p><p>Choice B is incorrect because the plural verb &ldquo;invite&rdquo; doesn&rsquo;t agree in number with the singular subject &ldquo;Tracy Fullerton&rsquo;s <em>Walden, a game</em>.&rdquo; Choice C is incorrect because the plural verb &ldquo;are inviting&rdquo; doesn&rsquo;t agree in number with the singular subject &ldquo;Tracy Fullerton&rsquo;s <em>Walden, a game</em>.&rdquo; Choice D is incorrect because the plural verb &ldquo;have invited&rdquo; doesn&rsquo;t agree in number with the singular subject &ldquo;Tracy Fullerton&rsquo;s <em>Walden, a game</em>.&rdquo;</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"ac7b8d04","external_id":"324fda2b-53dc-49f4-bd65-fd0a18a3b71c","vaultid":null,"uId":"dbf7f5c4-7e28-4b4a-964a-0213428778bc","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Tracy Fullerton&rsquo;s <em>Walden, a game</em>, an unlikely fusion of the writings of nineteenth-century transcendentalist Henry David Thoreau with today&rsquo;s open-world video games, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> players to explore a digital version of Walden Pond, the idyllic natural setting featured in Thoreau&rsquo;s book <em>Walden</em>.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"ecac84ae-1f84-40c5-b8f5-3d777f2f5f66","content":"<p>invites</p>"},{"id":"0f01ead9-362b-48b0-be9c-d5fbabb9b37b","content":"<p>invite</p>"},{"id":"9cacaaad-ce86-4317-8aba-b8c1c4fc7f61","content":"<p>are inviting</p>"},{"id":"70378c05-36e1-41da-a508-2762b2494bfb","content":"<p>have invited</p>"}],"keys":["ecac84ae-1f84-40c5-b8f5-3d777f2f5f66"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is subject-verb agreement. The singular verb &ldquo;invites&rdquo; agrees in number with the singular subject &ldquo;Tracy Fullerton&rsquo;s <em>Walden, a game</em>.&rdquo;</p><p>Choice B is incorrect because the plural verb &ldquo;invite&rdquo; doesn&rsquo;t agree in number with the singular subject &ldquo;Tracy Fullerton&rsquo;s <em>Walden, a game</em>.&rdquo; Choice C is incorrect because the plural verb &ldquo;are inviting&rdquo; doesn&rsquo;t agree in number with the singular subject &ldquo;Tracy Fullerton&rsquo;s <em>Walden, a game</em>.&rdquo; Choice D is incorrect because the plural verb &ldquo;have invited&rdquo; doesn&rsquo;t agree in number with the singular subject &ldquo;Tracy Fullerton&rsquo;s <em>Walden, a game</em>.&rdquo;</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771168,"updateDate":1776362771168}$SATQ$::jsonb, 1776362771168, 1776362771168),
    ($SATQ$ace95f84$SATQ$, $SATQ$fd647ae7-ec37-4389-826c-c5e2146d2aa8$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>By analyzing the level of radioactive decay within a fossil specimen, scientists can establish the age of that fossil with a high degree of precision. When radioactive elements aren&rsquo;t present, scientists turn to <span aria-hidden="true">______</span><span class="sr-only">blank</span> analysis of Earth&rsquo;s sediment layers (strata)&mdash;to estimate how old a fossil is based on the age of the strata in which the fossil is found.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"5789abda-d57f-4e4b-aae6-9edaaaf24968","content":"<p>stratigraphy&mdash;the</p>"},{"id":"04e48166-dbce-4938-b08e-4c17a7c16437","content":"<p>stratigraphy (the</p>"},{"id":"450c698c-524c-454b-9ede-85154b31e7dd","content":"<p>stratigraphy: the</p>"},{"id":"9a3f3558-e983-48c2-8425-0fd54322c3e2","content":"<p>stratigraphy, the</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["5789abda-d57f-4e4b-aae6-9edaaaf24968"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of punctuation within a sentence. The dash after "stratigraphy" pairs with the dash after "(strata)" to separate the supplementary element "the analysis of Earth&rsquo;s sediment layers (strata)" from the rest of the sentence. This supplementary element functions to define the term "stratigraphy," and the pair of dashes indicates that this element could be removed without affecting the grammatical coherence of the sentence.</p><p>Choice B is incorrect because a parenthesis can&rsquo;t be paired with a dash in this way to separate the supplementary element from the rest of the sentence. Choice C is incorrect because a colon can&rsquo;t be paired with a dash in this way to separate the supplementary element from the rest of the sentence. Choice D is incorrect because a comma can&rsquo;t be paired with a dash in this way to separate the supplementary element from the rest of the sentence.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"ace95f84","external_id":"fd647ae7-ec37-4389-826c-c5e2146d2aa8","vaultid":null,"uId":"7097b2bf-4b00-4252-b598-bc0f4d717edb","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>By analyzing the level of radioactive decay within a fossil specimen, scientists can establish the age of that fossil with a high degree of precision. When radioactive elements aren&rsquo;t present, scientists turn to <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> analysis of Earth&rsquo;s sediment layers (strata)&mdash;to estimate how old a fossil is based on the age of the strata in which the fossil is found.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"5789abda-d57f-4e4b-aae6-9edaaaf24968","content":"<p>stratigraphy&mdash;the</p>"},{"id":"04e48166-dbce-4938-b08e-4c17a7c16437","content":"<p>stratigraphy (the</p>"},{"id":"450c698c-524c-454b-9ede-85154b31e7dd","content":"<p>stratigraphy: the</p>"},{"id":"9a3f3558-e983-48c2-8425-0fd54322c3e2","content":"<p>stratigraphy, the</p>"}],"keys":["5789abda-d57f-4e4b-aae6-9edaaaf24968"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of punctuation within a sentence. The dash after \"stratigraphy\" pairs with the dash after \"(strata)\" to separate the supplementary element \"the analysis of Earth&rsquo;s sediment layers (strata)\" from the rest of the sentence. This supplementary element functions to define the term \"stratigraphy,\" and the pair of dashes indicates that this element could be removed without affecting the grammatical coherence of the sentence.</p><p>Choice B is incorrect because a parenthesis can&rsquo;t be paired with a dash in this way to separate the supplementary element from the rest of the sentence. Choice C is incorrect because a colon can&rsquo;t be paired with a dash in this way to separate the supplementary element from the rest of the sentence. Choice D is incorrect because a comma can&rsquo;t be paired with a dash in this way to separate the supplementary element from the rest of the sentence.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323047,"updateDate":1730147323047}$SATQ$::jsonb, 1730147323047, 1730147323047),
    ($SATQ$acf454af$SATQ$, $SATQ$dbd12d8c-8c80-4050-90a8-fe2e239abf44$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>An online content creator who uses copyrighted songs without permission risks being demonetized (prohibited from including paid advertisements in content). The best way to avoid demonetization is to choose music from the public domain. Using one of these noncopyrighted songs <span aria-hidden="true">______</span><span class="sr-only">blank</span> a creator won&rsquo;t lose advertising revenue.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"dd719403-66a5-47ce-8e48-1a3bc8db715c","content":"<p>are ensuring</p>"},{"id":"b5c571c4-d118-4ac0-b008-92bba7ab5abf","content":"<p>have ensured</p>"},{"id":"90e39724-1b35-455f-9119-12459b868228","content":"<p>ensure</p>"},{"id":"42bd7260-5adc-4a6c-8ea5-6230554ea2d7","content":"<p>ensures</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["42bd7260-5adc-4a6c-8ea5-6230554ea2d7"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is subject-verb agreement. The singular verb "ensures" agrees in number with the singular subject "using."</p><p>Choice A is incorrect because the plural verb "are ensuring" doesn&rsquo;t agree in number with the singular subject "using." Choice B is incorrect because the plural verb "have ensured" doesn&rsquo;t agree in number with the singular subject "using." Choice C is incorrect because the plural verb "ensure" doesn&rsquo;t agree in number with the singular subject "using."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"acf454af","external_id":"dbd12d8c-8c80-4050-90a8-fe2e239abf44","vaultid":null,"uId":"52549bd2-88c7-438a-8f5f-573024d6eacf","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>An online content creator who uses copyrighted songs without permission risks being demonetized (prohibited from including paid advertisements in content). The best way to avoid demonetization is to choose music from the public domain. Using one of these noncopyrighted songs <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> a creator won&rsquo;t lose advertising revenue.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"dd719403-66a5-47ce-8e48-1a3bc8db715c","content":"<p>are ensuring</p>"},{"id":"b5c571c4-d118-4ac0-b008-92bba7ab5abf","content":"<p>have ensured</p>"},{"id":"90e39724-1b35-455f-9119-12459b868228","content":"<p>ensure</p>"},{"id":"42bd7260-5adc-4a6c-8ea5-6230554ea2d7","content":"<p>ensures</p>"}],"keys":["42bd7260-5adc-4a6c-8ea5-6230554ea2d7"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is subject-verb agreement. The singular verb \"ensures\" agrees in number with the singular subject \"using.\"</p><p>Choice A is incorrect because the plural verb \"are ensuring\" doesn&rsquo;t agree in number with the singular subject \"using.\" Choice B is incorrect because the plural verb \"have ensured\" doesn&rsquo;t agree in number with the singular subject \"using.\" Choice C is incorrect because the plural verb \"ensure\" doesn&rsquo;t agree in number with the singular subject \"using.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323049,"updateDate":1730147323049}$SATQ$::jsonb, 1730147323049, 1730147323049),
    ($SATQ$ad046778$SATQ$, $SATQ$03a35c10-fe90-4240-9d2b-687104c00775$SATQ$::uuid, $SATQ$9f1169a6-d5f5-4163-aca7-e84bbb5d0acc$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>To humans, it does not appear that the golden orb-weaver spider uses camouflage to capture its <span aria-hidden="true">______</span><span class="sr-only">blank</span> the brightly colored arachnid seems to wait conspicuously in the center of its large circular web for insects to approach. Researcher Po Peng of the University of Melbourne has explained that the spider&rsquo;s distinctive coloration may in fact be part of its appeal.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"a7b92627-e873-441a-bfdc-c975ac692ec8","content":"<p>prey, rather,</p>"},{"id":"d4ed64ee-dd60-4425-8ea7-fa115cc05e77","content":"<p>prey rather,</p>"},{"id":"098bb225-19e1-4991-83f0-53e25caaf1d9","content":"<p>prey, rather;</p>"},{"id":"b41b59b1-301e-4240-8c97-d75231f4ebce","content":"<p>prey; rather,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["b41b59b1-301e-4240-8c97-d75231f4ebce"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the coordination of main clauses within a sentence. The semicolon is correctly used to join the first main clause (&ldquo;To humans&hellip;prey&rdquo;) and the second main clause (&ldquo;rather&hellip;approach&rdquo;). Further, the comma after the adverb &ldquo;rather&rdquo; is correctly used to separate the adverb from the main clause (&ldquo;the brightly&hellip;approach&rdquo;) it modifies, logically indicating that the information in this clause (how the spider&rsquo;s behavior appears to humans) is contrary to the information in the previous clause (how the spider&rsquo;s behavior does not appear to humans). </p><p>Choice A is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join two main clauses. Choice B is incorrect because it results in a run-on sentence. The two main clauses are fused without appropriate punctuation and/or a conjunction. Choice C is incorrect. Placing the comma between the first main clause &ldquo;To humans&hellip;prey&rdquo; and the adverb &ldquo;rather&rdquo; illogically indicates that the information in the first main clause is contrary to what came before, which doesn&rsquo;t make sense in this context. </p>$SATQ$, false, 0, $SATQ$OSP-606-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$1256c83f-2223-4389-a314-532d3427bdc2$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"ad046778","external_id":"03a35c10-fe90-4240-9d2b-687104c00775","vaultid":"9f1169a6-d5f5-4163-aca7-e84bbb5d0acc","uId":"c8e12649-3d27-4fee-81a0-b81d03c39a35","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>To humans, it does not appear that the golden orb-weaver spider uses camouflage to capture its <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the brightly colored arachnid seems to wait conspicuously in the center of its large circular web for insects to approach. Researcher Po Peng of the University of Melbourne has explained that the spider&rsquo;s distinctive coloration may in fact be part of its appeal.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"a7b92627-e873-441a-bfdc-c975ac692ec8","content":"<p>prey, rather,</p>"},{"id":"d4ed64ee-dd60-4425-8ea7-fa115cc05e77","content":"<p>prey rather,</p>"},{"id":"098bb225-19e1-4991-83f0-53e25caaf1d9","content":"<p>prey, rather;</p>"},{"id":"b41b59b1-301e-4240-8c97-d75231f4ebce","content":"<p>prey; rather,</p>"}],"keys":["b41b59b1-301e-4240-8c97-d75231f4ebce"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the coordination of main clauses within a sentence. The semicolon is correctly used to join the first main clause (&ldquo;To humans&hellip;prey&rdquo;) and the second main clause (&ldquo;rather&hellip;approach&rdquo;). Further, the comma after the adverb &ldquo;rather&rdquo; is correctly used to separate the adverb from the main clause (&ldquo;the brightly&hellip;approach&rdquo;) it modifies, logically indicating that the information in this clause (how the spider&rsquo;s behavior appears to humans) is contrary to the information in the previous clause (how the spider&rsquo;s behavior does not appear to humans). </p><p>Choice A is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join two main clauses. Choice B is incorrect because it results in a run-on sentence. The two main clauses are fused without appropriate punctuation and/or a conjunction. Choice C is incorrect. Placing the comma between the first main clause &ldquo;To humans&hellip;prey&rdquo; and the adverb &ldquo;rather&rdquo; illogically indicates that the information in the first main clause is contrary to what came before, which doesn&rsquo;t make sense in this context. </p>","parenttemplatename":"OSP-606-SEC","parenttemplateid":"","templateclusterid":"1256c83f-2223-4389-a314-532d3427bdc2","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959339,"updateDate":1691007959339}$SATQ$::jsonb, 1691007959339, 1691007959339),
    ($SATQ$adf210e7$SATQ$, $SATQ$3867bb67-ce72-40ca-a140-79b0a6b50603$SATQ$::uuid, $SATQ$1ffde6a4-8ba8-418d-b807-4e47a9b76273$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>The haiku-like poems of Tomas Transtr&ouml;mer, which present nature- and dream-influenced images in crisp, spare language, have earned the Swedish poet praise from leading contemporary <span aria-hidden="true">______</span><span class="sr-only">blank</span> them Nigerian American essayist and novelist Teju Cole, who has written that Transtr&ouml;mer&rsquo;s works &ldquo;contain a luminous simplicity.&rdquo;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"c7a4b1e1-fb34-4c8c-9578-2044c5eff575","content":"<p>writers. Among&nbsp;</p>"},{"id":"10f39094-dac6-408b-8b81-f3ef07e5e157","content":"<p>writers among&nbsp;</p>"},{"id":"376a9394-950b-4a9d-b972-07bb999e8ccd","content":"<p>writers; among&nbsp;</p>"},{"id":"261113f3-8da3-47eb-8b29-52a9cf7ecdb1","content":"<p>writers, among&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["261113f3-8da3-47eb-8b29-52a9cf7ecdb1"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is punctuation use between a main clause and a supplementary phrase. This choice correctly uses a comma to mark the boundary between the main clause (&ldquo;The haiku-like&hellip;writers&rdquo;) and the supplementary phrase (&ldquo;among&hellip;Cole&rdquo;) that specifies a contemporary writer who has praised Tomas Transtr&ouml;mer&rsquo;s haiku-like poems.&nbsp;</p><p>Choice A is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with &ldquo;among.&rdquo; Choice B is incorrect because it fails to mark the boundary between the main clause and the supplementary phrase with appropriate punctuation. Choice C is incorrect because a semicolon can&rsquo;t be used in this way to join the main clause (&ldquo;The haiku-like&hellip;writers&rdquo;) and the supplementary phrase (&ldquo;among&hellip;Cole&rdquo;).&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-791-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$79934902-30ad-4285-a290-971d0fa58729$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"adf210e7","external_id":"3867bb67-ce72-40ca-a140-79b0a6b50603","vaultid":"1ffde6a4-8ba8-418d-b807-4e47a9b76273","uId":"0a99b297-9dbd-46ab-8799-3ddf82b560ac","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>The haiku-like poems of Tomas Transtr&ouml;mer, which present nature- and dream-influenced images in crisp, spare language, have earned the Swedish poet praise from leading contemporary <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> them Nigerian American essayist and novelist Teju Cole, who has written that Transtr&ouml;mer&rsquo;s works &ldquo;contain a luminous simplicity.&rdquo;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"c7a4b1e1-fb34-4c8c-9578-2044c5eff575","content":"<p>writers. Among&nbsp;</p>"},{"id":"10f39094-dac6-408b-8b81-f3ef07e5e157","content":"<p>writers among&nbsp;</p>"},{"id":"376a9394-950b-4a9d-b972-07bb999e8ccd","content":"<p>writers; among&nbsp;</p>"},{"id":"261113f3-8da3-47eb-8b29-52a9cf7ecdb1","content":"<p>writers, among&nbsp;</p>"}],"keys":["261113f3-8da3-47eb-8b29-52a9cf7ecdb1"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is punctuation use between a main clause and a supplementary phrase. This choice correctly uses a comma to mark the boundary between the main clause (&ldquo;The haiku-like&hellip;writers&rdquo;) and the supplementary phrase (&ldquo;among&hellip;Cole&rdquo;) that specifies a contemporary writer who has praised Tomas Transtr&ouml;mer&rsquo;s haiku-like poems.&nbsp;</p><p>Choice A is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with &ldquo;among.&rdquo; Choice B is incorrect because it fails to mark the boundary between the main clause and the supplementary phrase with appropriate punctuation. Choice C is incorrect because a semicolon can&rsquo;t be used in this way to join the main clause (&ldquo;The haiku-like&hellip;writers&rdquo;) and the supplementary phrase (&ldquo;among&hellip;Cole&rdquo;).&nbsp;</p>","parenttemplatename":"OSP-791-SEC","parenttemplateid":"","templateclusterid":"79934902-30ad-4285-a290-971d0fa58729","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959353,"updateDate":1691007959353}$SATQ$::jsonb, 1691007959353, 1691007959353),
    ($SATQ$ae439895$SATQ$, $SATQ$cb2be4fe-d06f-40eb-aca3-805b00f0841d$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>In her 1983 book <em>The Managed Heart: Commercialization of Human Feeling</em>, sociologist Arlie Russell Hochschild first explored at length her conception of a &ldquo;sociology of emotions&rdquo;&mdash;the idea that the various cultural and ideological frameworks a person has internalized (class, gender, political affiliation, etc.) <span aria-hidden="true">______</span><span class="sr-only">blank</span> each emotional reaction that person has within a situation.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"7fd297f0-2874-4b2f-b32b-9703eac2e1c2","content":"<p>underlies</p>"},{"id":"1f835d67-72d3-4910-a90d-a5a508aaec46","content":"<p>is underlying</p>"},{"id":"1a13357c-5be3-48e9-98e2-01c498e97fb8","content":"<p>underlie</p>"},{"id":"7954a44b-0293-45d2-a52f-64154abebafc","content":"<p>has been underlying</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["1a13357c-5be3-48e9-98e2-01c498e97fb8"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is subject-verb agreement. The plural verb "underlie" agrees in number with the plural subject "frameworks."</p><p>Choice A is incorrect because the singular verb "underlies" doesn&rsquo;t agree in number with the plural subject "frameworks." Choice B is incorrect because the singular verb "is underlying" doesn&rsquo;t agree in number with the plural subject "frameworks." Choice D is incorrect because the singular verb "has been underlying" doesn&rsquo;t agree in number with the plural subject "frameworks."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"q